#!/usr/bin/env python3
"""Task-scoped helper: prepend a cover page to report.pdf.

The cover page contains the exact title 'Annual Financial Report' and the
current date (operator runtime date via datetime.date.today()). The helper uses
the pdf skill's documented toolset, trying each in order:
- creation: reportlab canvas ("reportlab - Create PDFs"), falling back to a
  standard-library minimal PDF content stream (same content, no dependencies)
- merge: pypdf ("pypdf - Basic Operations" -> "Merge PDFs"), pypdfium2
  (reference.md), qpdf CLI ("Command-Line Tools" -> "qpdf"), or pdftk CLI
  ("Command-Line Tools" -> "pdftk")
- validation: pypdf extract_text / pdftotext / pypdfium2 get_text (reference.md),
  and page counts via pypdf / qpdf --show-npages / pdftk dump_data / pypdfium2

Only report.pdf is modified; temporary cover/merge files are created next to it
and removed afterwards. The result is validated in place.
"""
import datetime
import io
import os
import re
import shutil
import subprocess
import sys

TITLE = "Annual Financial Report"
DATE_STR = datetime.date.today().strftime("%B %d, %Y")
REPORT = "report.pdf"
PAGE_W = 612.0
PAGE_H = 792.0


# ---------------------------------------------------------------- cover build

def _pdf_escape(text: str) -> str:
    return text.replace("\\", r"\\").replace("(", r"\(").replace(")", r"\)")


def _approx_width(text: str, size: float) -> float:
    # Helvetica-Bold approximate advance width: ~0.55 * font size per char
    return len(text) * 0.55 * size


def build_cover_bytes_reportlab() -> bytes:
    from reportlab.lib.pagesizes import letter
    from reportlab.pdfgen import canvas

    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=letter)
    width, height = letter
    c.setFont("Helvetica-Bold", 28)
    tw = c.stringWidth(TITLE, "Helvetica-Bold", 28)
    c.drawString((width - tw) / 2, height * 0.55, TITLE)
    c.setFont("Helvetica", 16)
    dw = c.stringWidth(DATE_STR, "Helvetica", 16)
    c.drawString((width - dw) / 2, height * 0.55 - 40, DATE_STR)
    c.save()
    return buf.getvalue()


def build_cover_bytes_stdlib() -> bytes:
    """Minimal valid one-page PDF via the standard library (vector text)."""
    title_size, date_size = 28.0, 16.0
    title_x = (PAGE_W - _approx_width(TITLE, title_size)) / 2
    date_x = (PAGE_W - _approx_width(DATE_STR, date_size)) / 2
    title_y = PAGE_H * 0.55
    date_y = title_y - 40.0

    content = (
        "BT\n"
        f"/F1 {title_size:.1f} Tf\n"
        f"{title_x:.2f} {title_y:.2f} Td\n"
        f"({_pdf_escape(TITLE)}) Tj\n"
        "ET\n"
        "BT\n"
        f"/F1 {date_size:.1f} Tf\n"
        f"{date_x:.2f} {date_y:.2f} Td\n"
        f"({_pdf_escape(DATE_STR)}) Tj\n"
        "ET\n"
    ).encode("latin-1")

    objects = [
        b"<< /Type /Catalog /Pages 2 0 R >>",
        b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
        (
            b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] "
            b"/Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>"
        ),
        b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>",
        b"<< /Length " + str(len(content)).encode("ascii") + b" >>\nstream\n"
        + content
        + b"\nendstream",
    ]

    out = bytearray(b"%PDF-1.4\n")
    offsets = []
    for i, body in enumerate(objects, start=1):
        offsets.append(len(out))
        out += f"{i} 0 obj\n".encode("ascii") + body + b"\nendobj\n"

    xref_pos = len(out)
    out += f"xref\n0 {len(objects) + 1}\n".encode("ascii")
    out += b"0000000000 65535 f \n"
    for off in offsets:
        out += f"{off:010d} 00000 n \n".encode("ascii")
    out += (
        f"trailer\n<< /Size {len(objects) + 1} /Root 1 0 R >>\n"
        f"startxref\n{xref_pos}\n%%EOF\n"
    ).encode("ascii")
    return bytes(out)


def build_cover_bytes() -> tuple:
    try:
        import reportlab  # noqa: F401

        return build_cover_bytes_reportlab(), "reportlab"
    except ImportError:
        return build_cover_bytes_stdlib(), "stdlib"


# ------------------------------------------------------------------ merge

def merge_with_pypdf(cover_bytes: bytes, report_path: str) -> None:
    from pypdf import PdfReader, PdfWriter

    reader = PdfReader(report_path)
    writer = PdfWriter()
    writer.add_page(PdfReader(io.BytesIO(cover_bytes)).pages[0])
    for page in reader.pages:
        writer.add_page(page)
    with open(report_path, "wb") as fh:
        writer.write(fh)


def merge_with_pypdfium2(cover_bytes: bytes, report_path: str) -> None:
    import pypdfium2 as pdfium

    base = os.path.dirname(os.path.abspath(report_path))
    cover_path = os.path.join(base, ".cover_tmp.pdf")
    out_path = os.path.join(base, ".merged_tmp.pdf")
    try:
        with open(cover_path, "wb") as fh:
            fh.write(cover_bytes)
        cover = pdfium.PdfDocument(cover_path)
        src = pdfium.PdfDocument(report_path)
        out = pdfium.PdfDocument.new()
        out.import_pages(cover)
        out.import_pages(src)
        out.save(out_path)
        out.close()
        src.close()
        cover.close()
        os.replace(out_path, report_path)
    finally:
        for path in (cover_path, out_path):
            if os.path.exists(path):
                os.remove(path)


def _cli_merge(cmd_cover_first: list, report_path: str) -> None:
    base = os.path.dirname(os.path.abspath(report_path))
    out_path = os.path.join(base, ".merged_tmp.pdf")
    result = subprocess.run(
        cmd_cover_first + [out_path], capture_output=True, text=True
    )
    if result.returncode != 0:
        raise SystemExit(f"merge failed: {result.stderr.strip()}")
    os.replace(out_path, report_path)


def merge_with_qpdf(cover_path: str, report_path: str) -> None:
    _cli_merge(
        ["qpdf", "--empty", "--pages", cover_path, report_path, "--"], report_path
    )


def merge_with_pdftk(cover_path: str, report_path: str) -> None:
    _cli_merge(["pdftk", cover_path, report_path, "cat", "output"], report_path)


def _write_temp_cover(cover_bytes: bytes) -> str:
    base = os.path.dirname(os.path.abspath(REPORT))
    cover_path = os.path.join(base, ".cover_tmp.pdf")
    with open(cover_path, "wb") as fh:
        fh.write(cover_bytes)
    return cover_path


# -------------------------------------------------------------- page counts

def count_pages_pypdf(path: str) -> int:
    from pypdf import PdfReader

    return len(PdfReader(path).pages)


def count_pages_pypdfium2(path: str) -> int:
    import pypdfium2 as pdfium

    doc = pdfium.PdfDocument(path)
    try:
        return len(doc)
    finally:
        doc.close()


def count_pages_qpdf(path: str) -> int:
    result = subprocess.run(
        ["qpdf", "--show-npages", path], capture_output=True, text=True
    )
    if result.returncode != 0:
        raise SystemExit(f"qpdf --show-npages failed: {result.stderr.strip()}")
    return int(result.stdout.strip())


def count_pages_pdftk(path: str) -> int:
    result = subprocess.run(
        ["pdftk", path, "dump_data"], capture_output=True, text=True
    )
    if result.returncode != 0:
        raise SystemExit(f"pdftk dump_data failed: {result.stderr.strip()}")
    match = re.search(r"NumberOfPages:\s*(\d+)", result.stdout)
    if not match:
        raise SystemExit("pdftk dump_data: NumberOfPages not found")
    return int(match.group(1))


def count_pages(path: str) -> int:
    try:
        return count_pages_pypdf(path)
    except ImportError:
        pass
    try:
        return count_pages_pypdfium2(path)
    except ImportError:
        pass
    if shutil.which("qpdf"):
        return count_pages_qpdf(path)
    if shutil.which("pdftk"):
        return count_pages_pdftk(path)
    raise SystemExit("no documented page-count tool available")


# ------------------------------------------------------------------ text

def page1_text_pypdf(path: str) -> str:
    from pypdf import PdfReader

    return PdfReader(path).pages[0].extract_text() or ""


def page1_text_pypdfium2(path: str) -> str:
    import pypdfium2 as pdfium

    doc = pdfium.PdfDocument(path)
    try:
        return doc[0].get_text() or ""
    finally:
        doc.close()


def page1_text_pdftotext(path: str) -> str:
    result = subprocess.run(
        ["pdftotext", "-f", "1", "-l", "1", path, "-"],
        capture_output=True,
        text=True,
    )
    if result.returncode != 0:
        raise SystemExit(f"pdftotext failed: {result.stderr.strip()}")
    return result.stdout


def page1_text(path: str) -> str:
    try:
        return page1_text_pypdf(path)
    except ImportError:
        pass
    if shutil.which("pdftotext"):
        return page1_text_pdftotext(path)
    try:
        return page1_text_pypdfium2(path)
    except ImportError:
        pass
    return ""


# ------------------------------------------------------------------- main

def main() -> None:
    if not os.path.exists(REPORT):
        raise SystemExit(f"error: {REPORT} not found in the working directory")

    cover_bytes, cover_method = build_cover_bytes()
    original_pages = count_pages(REPORT)

    has_pypdf = True
    try:
        import pypdf  # noqa: F401
    except ImportError:
        has_pypdf = False

    merge_method = None
    if has_pypdf:
        merge_with_pypdf(cover_bytes, REPORT)
        merge_method = "pypdf"
    else:
        try:
            import pypdfium2  # noqa: F401

            merge_with_pypdfium2(cover_bytes, REPORT)
            merge_method = "pypdfium2"
        except ImportError:
            pass
    if merge_method is None and shutil.which("qpdf"):
        cover_path = _write_temp_cover(cover_bytes)
        try:
            merge_with_qpdf(cover_path, REPORT)
            merge_method = "qpdf"
        finally:
            if os.path.exists(cover_path):
                os.remove(cover_path)
    if merge_method is None and shutil.which("pdftk"):
        cover_path = _write_temp_cover(cover_bytes)
        try:
            merge_with_pdftk(cover_path, REPORT)
            merge_method = "pdftk"
        finally:
            if os.path.exists(cover_path):
                os.remove(cover_path)
    if merge_method is None:
        raise SystemExit(
            "no documented merge tool available (install pypdf, pypdfium2, "
            "qpdf, or pdftk)"
        )

    # Validate: page count grew by exactly one and page 1 shows title + date
    final_pages = count_pages(REPORT)
    if final_pages != original_pages + 1:
        raise SystemExit(
            f"validation failed: expected {original_pages + 1} pages, "
            f"got {final_pages}"
        )
    text = page1_text(REPORT)
    if TITLE not in text:
        raise SystemExit("validation failed: cover page title missing")
    if DATE_STR not in text:
        raise SystemExit("validation failed: cover page date missing")

    print(
        f"Cover page prepended (cover via {cover_method}, merge via {merge_method}): "
        f"title={TITLE!r}, date={DATE_STR!r}; pages {original_pages} -> {final_pages}"
    )


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Task-scoped helper: prepend a cover page to report.pdf.

The cover page contains the exact title 'Annual Financial Report' and the
current date (operator runtime date via datetime.date.today()).

With no arguments, the helper performs the transformation and in-place
validation using the first available pdf-skill-documented toolchain:
- creation: reportlab canvas, else a standard-library minimal PDF content
  stream (same vector text content, no dependencies)
- merge: pypdf -> pypdfium2 -> qpdf CLI -> pdftk CLI -> PIL/pdf2image raster
  merge (the toolchain used by the skill's own helper scripts)
- validation: pypdf extract_text / pdftotext / pypdfium2 get_text, and page
  counts via pypdf / pypdfium2 / qpdf --show-npages / pdftk dump_data

With '--probe', it only reports which of those tools are available in this
runtime (needed to choose the merge implementation) without modifying files.

Only report.pdf is modified; temporary cover/merge files are created next to it
and removed afterwards.
"""
import datetime
import io
import os
import re
import shutil
import subprocess
import sys

TITLE = "Annual Financial Report"
DATE_STR = datetime.date.today().strftime("%B %d, %Y")
REPORT = "report.pdf"
PAGE_W = 612.0
PAGE_H = 792.0


# ---------------------------------------------------------------- cover build

