    ).encode("ascii")
    return bytes(out)


def build_cover_bytes() -> tuple:
    try:
        import reportlab  # noqa: F401

        return build_cover_bytes_reportlab(), "reportlab"
    except ImportError:
        return build_cover_bytes_stdlib(), "stdlib"


# ------------------------------------------------------------------ merge

def merge_with_pypdf(cover_bytes: bytes, report_path: str) -> None:
    from pypdf import PdfReader, PdfWriter

    reader = PdfReader(report_path)
    writer = PdfWriter()
    writer.add_page(PdfReader(io.BytesIO(cover_bytes)).pages[0])
    for page in reader.pages:
        writer.add_page(page)
    with open(report_path, "wb") as fh:
        writer.write(fh)


def merge_with_pypdfium2(cover_bytes: bytes, report_path: str) -> None:
    import pypdfium2 as pdfium

    base = os.path.dirname(os.path.abspath(report_path))
    cover_path = os.path.join(base, ".cover_tmp.pdf")
    out_path = os.path.join(base, ".merged_tmp.pdf")
    try:
        with open(cover_path, "wb") as fh:
            fh.write(cover_bytes)
        cover = pdfium.PdfDocument(cover_path)
        src = pdfium.PdfDocument(report_path)
        out = pdfium.PdfDocument.new()
        out.import_pages(cover)
        out.import_pages(src)
        out.save(out_path)
        out.close()
        src.close()
        cover.close()
        os.replace(out_path, report_path)
    finally:
        for path in (cover_path, out_path):
            if os.path.exists(path):
                os.remove(path)


def _cli_merge(cmd_cover_first: list, report_path: str) -> None:
    base = os.path.dirname(os.path.abspath(report_path))
    out_path = os.path.join(base, ".merged_tmp.pdf")
    result = subprocess.run(
        cmd_cover_first + [out_path], capture_output=True, text=True
    )
    if result.returncode != 0:
        raise SystemExit(f"merge failed: {result.stderr.strip()}")
    os.replace(out_path, report_path)


def merge_with_qpdf(cover_path: str, report_path: str) -> None:
    _cli_merge(["qpdf", "--empty", "--pages", cover_path, report_path, "--"], report_path)


def merge_with_pdftk(cover_path: str, report_path: str) -> None:
    _cli_merge(["pdftk", cover_path, report_path, "cat", "output"], report_path)


def merge_with_pil(cover_bytes: bytes, report_path: str) -> None:
    """Raster merge used only as a last resort (PIL + pdf2image)."""
    from PIL import Image, ImageDraw, ImageFont
    from pdf2image import convert_from_path

    width, height = 1240, 1754  # US Letter at ~150 dpi
    img = Image.new("RGB", (width, height), "white")
    draw = ImageDraw.Draw(img)

    def centered_font(size, bold):
        for name in (
            ("DejaVuSans-Bold.ttf", "DejaVuSans.ttf")
            if bold
            else ("DejaVuSans.ttf", "DejaVuSans-Bold.ttf")
        ):
            try:
                return ImageFont.truetype(name, size)
            except Exception:
                continue
        return ImageFont.load_default()

    title_font = centered_font(76, True)
    date_font = centered_font(42, False)
    tbbox = draw.textbbox((0, 0), TITLE, font=title_font)
    draw.text(((width - (tbbox[2] - tbbox[0])) / 2, height * 0.45), TITLE, fill="black", font=title_font)
    dbbox = draw.textbbox((0, 0), DATE_STR, font=date_font)
    draw.text(((width - (dbbox[2] - dbbox[0])) / 2, height * 0.45 + 130), DATE_STR, fill="black", font=date_font)

    pages = convert_from_path(report_path, dpi=150)
    pages.insert(0, img)
    base = os.path.dirname(os.path.abspath(report_path))
    out_path = os.path.join(base, ".merged_tmp.pdf")
    try:
        pages[0].save(out_path, "PDF", save_all=True, append_images=pages[1:])
        os.replace(out_path, report_path)
    finally:
        if os.path.exists(out_path):
            os.remove(out_path)


def _write_temp_cover(cover_bytes: bytes) -> str:
    base = os.path.dirname(os.path.abspath(REPORT))
    cover_path = os.path.join(base, ".cover_tmp.pdf")
    with open(cover_path, "wb") as fh:
        fh.write(cover_bytes)
    return cover_path


# -------------------------------------------------------------- page counts

def count_pages_pypdf(path: str) -> int:
