    draw = ImageDraw.Draw(img)

    def pick_font(size, bold):
        names = ("DejaVuSans-Bold.ttf", "DejaVuSans.ttf") if bold else ("DejaVuSans.ttf", "DejaVuSans-Bold.ttf")
        for name in names:
            try:
                return ImageFont.truetype(name, size)
            except Exception:
                continue
        return ImageFont.load_default()

    title_font = pick_font(76, True)
    date_font = pick_font(42, False)
    tbbox = draw.textbbox((0, 0), TITLE, font=title_font)
    draw.text(((width - (tbbox[2] - tbbox[0])) / 2, height * 0.45), TITLE, fill="black", font=title_font)
    dbbox = draw.textbbox((0, 0), DATE_STR, font=date_font)
    draw.text(((width - (dbbox[2] - dbbox[0])) / 2, height * 0.45 + 130), DATE_STR, fill="black", font=date_font)

    pages = convert_from_path(report_path, dpi=150)
    pages.insert(0, img)
    base = os.path.dirname(os.path.abspath(report_path))
    out_path = os.path.join(base, ".merged_tmp.pdf")
    try:
        pages[0].save(out_path, "PDF", save_all=True, append_images=pages[1:])
        os.replace(out_path, report_path)
    finally:
        if os.path.exists(out_path):
            os.remove(out_path)


def _write_temp_cover(cover_bytes: bytes) -> str:
    base = os.path.dirname(os.path.abspath(REPORT))
    cover_path = os.path.join(base, ".cover_tmp.pdf")
    with open(cover_path, "wb") as fh:
        fh.write(cover_bytes)
    return cover_path


# ------------------------------------------------------- stdlib PDF reading

class SimplePdf:
    """Minimal read-only PDF reader (classic xref tables and xref streams)."""

    def __init__(self, data: bytes):
        self.data = data
        self.entries = {}  # objnum -> ('off', offset) | ('stm', stm_num, idx)
        self.objects = {}  # objnum -> (dict_bytes, stream_bytes | None)
        self.root_num = None
        self.encrypt = False
        self._load()

    # -- lexer ----------------------------------------------------------
    @staticmethod
    def _tokens(data: bytes):
        toks = []
        i, n = 0, len(data)
        while i < n:
            c = data[i]
            if c in b" \t\r\n\f\0":
                i += 1
                continue
            if c == 37:  # %
                j = data.find(b"\n", i)
                i = n if j == -1 else j + 1
                continue
            if c == 47:  # /
                j = i + 1
                while j < n and data[j] not in b" \t\r\n\f()<>[]{}/%":
                    j += 1
                toks.append(("name", data[i:j]))
                i = j
                continue
            if c == 40:  # (
                depth, j = 1, i + 1
                while j < n and depth:
                    if data[j] == 92:  # backslash
                        j += 2
                        continue
                    if data[j] == 40:
                        depth += 1
                    elif data[j] == 41:
                        depth -= 1
                    j += 1
                toks.append(("str", data[i:j]))
                i = j
                continue
            if c == 60:  # <
                if i + 1 < n and data[i + 1] == 60:  # dict
                    depth, j = 1, i + 2
                    while j < n and depth:
                        if data[j:j + 2] == b"<<":
                            depth += 1
                            j += 2
                        elif data[j:j + 2] == b">>":
                            depth -= 1
                            j += 2
                        else:
                            j += 1
                    toks.append(("dict", data[i:j]))
                    i = j
                else:  # hex string
                    j = data.find(b">", i)
                    toks.append(("hex", data[i:j + 1]))
                    i = j + 1
                continue
            if c == 91:  # [
                j = i + 1
                while j < n and data[j] != 93:
                    j += 1
                toks.append(("array", data[i:j + 1]))
                i = j + 1
                continue
            if c in b"0123456789+-.":
                j = i + 1
                while j < n and data[j] in b"0123456789+-.":
                    j += 1
                toks.append(("num", data[i:j]))
                i = j
                continue
            # keyword
            j = i + 1
            while j < n and data[j] not in b" \t\r\n\f()<>[]{}/%":
                j += 1
            toks.append(("kw", data[i:j]))
            i = j
        return toks

    @staticmethod
    def _dict_of(tok):
        """tok is ('dict', b'<< ... >>') -> bytes content between << and >>."""
        return tok[1][2:-2]

    @staticmethod
    def _dict_get(dcontent: bytes, key: bytes):
        """Return raw bytes of the value following /key in a dict (no nesting)."""
        pat = re.compile(rb"/" + key + rb"(?![A-Za-z])\s*", re.S)
        m = pat.search(dcontent)
        if not m:
            return None
        rest = dcontent[m.end():]
        # value runs until the next top-level '/' key
        depth = 0
        j = 0
        while j < len(rest):
            c = rest[j]
            if c == 60 and rest[j:j + 2] == b"<<":
                depth += 1
                j += 2
                continue
            if c == 62 and rest[j:j + 2] == b">>":
                depth -= 1
                j += 2
                continue
            if c == 91:
                depth += 1
            elif c == 93:
                depth -= 1
            if depth == 0 and c == 47 and rest[j:j + 1] == b"/":
                break
            j += 1
        return rest[:j].strip()

    # -- xref -----------------------------------------------------------
    def _parse_classic_xref(self, pos: int):
        i = pos
        while True:
            m = re.match(rb"xref\s+", self.data[i:])
            if not m:
                break
            i += m.end()
            while True:
                sm = re.match(rb"(\d+)\s+(\d+)\s*", self.data[i:])
                if not sm:
                    break
                start, count = int(sm.group(1)), int(sm.group(2))
                i += sm.end()
                for k in range(count):
                    em = re.match(rb"(\d{10})\s+(\d{5})\s+([nf])\s*", self.data[i:])
                    if not em:
                        break
                    off, gen, kind = em.group(1), em.group(2), em.group(3)
                    num = start + k
                    if kind == b"n" and num not in self.entries:
                        self.entries[num] = ("off", int(off))
                    i += em.end()
            tm = re.match(rb"trailer\s*", self.data[i:])
            if not tm:
                break
            i += tm.end()
            # read dict token
            toks = self._tokens(self.data[i:])
            if toks and toks[0][0] == "dict":
                dcontent = self._dict_of(toks[0])
                root = self._dict_get(dcontent, b"Root")
                if root and root.endswith(b"R"):
                    self.root_num = int(root.split(b" ")[0])
                if self._dict_get(dcontent, b"Encrypt") is not None:
                    self.encrypt = True
                i += toks[0][1].__len__() + 1
            sm = re.search(rb"startxref\s+(\d+)", self.data[i:])
            if not sm:
                break
            pos = int(sm.group(1))
            i = pos

    def _parse_xref_stream(self, pos: int) -> dict:
        toks = self._tokens(self.data[pos:])
        if not toks or toks[0][0] != "num":
            raise SystemExit("xref stream parse failed")
        i = 1
        while toks[i][0] != "kw" or toks[i][1] != b"obj":
            i += 1
        i += 1
        if toks[i][0] != "dict":
            raise SystemExit("xref stream dict missing")
        dcontent = self._dict_of(toks[i])
        i += 1
        if toks[i][0] == "kw" and toks[i][1] == b"stream":
            i += 1
            # stream data until 'endstream'
            start = self.data.find(b"endstream", pos)
            stream_data = self.data[self.data.find(b"\n", self.data.find(b"stream", pos)) + 1:start]
            decoded = self._decode_stream(dcontent, stream_data)
        else:
            decoded = b""
        info = {
            "root": self._dict_get(dcontent, b"Root"),
            "encrypt": self._dict_get(dcontent, b"Encrypt"),
            "w": self._dict_get(dcontent, b"W"),
            "size": self._dict_get(dcontent, b"Size"),
            "index": self._dict_get(dcontent, b"Index"),
            "prev": self._dict_get(dcontent, b"Prev"),
            "decoded": decoded,
        }
        return info

    @staticmethod
    def _decode_stream(dcontent: bytes, stream_data: bytes) -> bytes:
        filt = SimplePdf._dict_get(dcontent, b"Filter")
        if filt is None or filt == b"/FlateDecode" or filt == b"/Fl":
            try:
                return zlib.decompress(stream_data)
            except zlib.error:
                return stream_data
        return stream_data

    def _parse_xref_entries(self, info: dict):
        w = [int(x) for x in info["w"].split()] if info["w"] else [1, 4, 2]
        idx = info["index"].split() if info["index"] else [b"0", info["size"]]
        pairs = [(int(idx[i]), int(idx[i + 1])) for i in range(0, len(idx), 2)]
        data = info["decoded"]
        pos = 0
        for start, count in pairs:
            for k in range(count):
                if pos + sum(w) > len(data):
                    break
                fields = []
                p = pos
                for width in w:
                    fields.append(int.from_bytes(data[p:p + width], "big"))
                    p += width
                pos = p
                typ, f2, f3 = fields
                num = start + k
                if typ == 1:
                    self.entries[num] = ("off", f2)
                elif typ == 2:
                    self.entries[num] = ("stm", f2, f3)
        if info["encrypt"] is not None:
            self.encrypt = True
        if info["root"] and info["root"].endswith(b"R"):
            self.root_num = int(info["root"].split(b" ")[0])
        if info["prev"] and info["prev"].endswith(b"0"):
            prev = int(info["prev"].split(b" ")[0])
            self._parse_xref_stream(prev)  # recursively follow /Prev

    # -- object loading -------------------------------------------------
    def _parse_object_at(self, off: int):
        toks = self._tokens(self.data[off:])
        if not toks or toks[0][0] != "num":
            return
        i = 1
        while i < len(toks) and not (toks[i][0] == "kw" and toks[i][1] == b"obj"):
            i += 1
        i += 1
        if i >= len(toks) or toks[i][0] != "dict":
            return
        dcontent = self._dict_of(toks[i])
        i += 1
        stream = None
        if i < len(toks) and toks[i][0] == "kw" and toks[i][1] == b"stream":
            i += 1
            start = self.data.find(b"endstream", off)
            # stream data begins after the first newline following 'stream'
            spos = self.data.find(b"stream", off) + len(b"stream")
            if self.data[spos:spos + 2] == b"\r\n":
                spos += 2
            elif self.data[spos:spos + 1] == b"\n":
                spos += 1
            stream = self.data[spos:start]
        return dcontent, stream

    def _load(self):
        sx = self.data.rfind(b"startxref")
        if sx == -1:
            raise SystemExit("report.pdf: startxref not found")
        m = re.search(rb"startxref\s+(\d+)", self.data[sx:])
        pos = int(m.group(1))
        if self.data[pos:pos + 4] == b"xref":
            self._parse_classic_xref(pos)
        else:
            info = self._parse_xref_stream(pos)
            self._parse_xref_entries(info)
        if self.encrypt:
            raise SystemExit("report.pdf is encrypted; cannot merge without a password")
        if self.root_num is None:
            raise SystemExit("report.pdf: /Root not found")
        # Load offset objects (including object streams lazily on demand)
        for num, kind in list(self.entries.items()):
            if kind[0] == "off":
                parsed = self._parse_object_at(kind[1])
                if parsed:
                    self.objects[num] = parsed

    def _resolve(self, ref: bytes):
        """ref like b'12 0 R' -> (dict_bytes, stream_bytes|None) of object 12."""
        if ref is None:
            return None
        num = int(ref.split(b" ")[0])
        if num in self.objects:
            return self.objects[num]
        entry = self.entries.get(num)
        if entry is None:
            return None
        if entry[0] == "off":
            parsed = self._parse_object_at(entry[1])
            if parsed:
                self.objects[num] = parsed
                return parsed
            return None
        # object inside an object stream
        _, stm_num, idx = entry
        stm = self._resolve_objstm(stm_num)
        if stm is None or idx >= len(stm):
            return None
        return stm[idx]

    def _resolve_objstm(self, stm_num: int):
        if stm_num in self.objects and self.objects[stm_num][1] is not None:
            dcontent, stream = self.objects[stm_num]
            n = int(SimplePdf._dict_get(dcontent, b"N") or b"0")
            first = int(SimplePdf._dict_get(dcontent, b"First") or b"0")
            decoded = self._decode_stream(dcontent, stream)
            header = decoded[:first]
            toks = SimplePdf._tokens(header)
            pairs = []
            for j in range(0, len(toks), 2):
                if j + 1 < len(toks) and toks[j][0] == "num" and toks[j + 1][0] == "num":
                    pairs.append((int(toks[j][1]), int(toks[j + 1][1])))
            out = []
            for objnum, offset in pairs:
                seg = decoded[first + offset:]
                toks2 = SimplePdf._tokens(seg)
                if toks2 and toks2[0][0] == "dict":
                    out.append((self._dict_of(toks2[0]), None))
                else:
                    out.append((None, None))
            return out
        return None

    # -- high level -----------------------------------------------------
    def page_count(self) -> int:
        root = self._resolve(self.root_ref())
        if not root:
            return 0
        pages_ref = self._dict_get(root[0], b"Pages")
        pages = self._resolve(pages_ref)
        if not pages:
            return 0
        count = self._dict_get(pages[0], b"Count")
        return int(count or b"0")

    def root_ref(self) -> bytes:
        return f"{self.root_num} 0 R".encode()

    def _collect_pages(self, pages_ref: bytes, out: list):
        pages = self._resolve(pages_ref)
        if not pages:
            return
        kids = self._dict_get(pages[0], b"Kids")
        if kids is None:
            return
        for ref in re.findall(rb"\d+\s+\d+\s+R", kids):
            kid = self._resolve(ref)
            if not kid:
                continue
            typ = self._dict_get(kid[0], b"Type")
            if typ == b"/Pages" or (typ is None and self._dict_get(kid[0], b"Kids") is not None):
                self._collect_pages(ref, out)
            else:
                out.append(ref)

    def page_contents(self, page_index: int) -> bytes:
        """Return decoded content stream bytes of the 1-based page_index."""
        root = self._resolve(self.root_ref())
        pages_ref = self._dict_get(root[0], b"Pages")
        pages = []
        self._collect_pages(pages_ref, pages)
        if page_index < 1 or page_index > len(pages):
            return b""
        page = self._resolve(pages[page_index - 1])
        if not page:
            return b""
        contents = self._dict_get(page[0], b"Contents")
        if contents is None:
            return b""
        out = b""
        refs = re.findall(rb"\d+\s+\d+\s+R", contents)
        if refs:
            for ref in refs:
                obj = self._resolve(ref)
                if obj and obj[1] is not None:
                    out += self._decode_stream(obj[0], obj[1])
        else:
            # /Contents could be an inline stream dict? rare; try resolving as ref
            ref = contents
            obj = self._resolve(ref)
            if obj and obj[1] is not None:
                out += self._decode_stream(obj[0], obj[1])
        return out


# -------------------------------------------------------------- page counts

def count_pages_pypdf(path: str) -> int:
    from pypdf import PdfReader

    return len(PdfReader(path).pages)


def count_pages_pypdfium2(path: str) -> int:
    import pypdfium2 as pdfium

    doc = pdfium.PdfDocument(path)
    try:
        return len(doc)
    finally:
        doc.close()


def count_pages_qpdf(path: str) -> int:
    result = subprocess.run(
        ["qpdf", "--show-npages", path], capture_output=True, text=True
    )
    if result.returncode != 0:
        raise SystemExit(f"qpdf --show-npages failed: {result.stderr.strip()}")
    return int(result.stdout.strip())


def count_pages_pdftk(path: str) -> int:
    result = subprocess.run(
        ["pdftk", path, "dump_data"], capture_output=True, text=True
    )
    if result.returncode != 0:
        raise SystemExit(f"pdftk dump_data failed: {result.stderr.strip()}")
    match = re.search(r"NumberOfPages:\s*(\d+)", result.stdout)
    if not match:
        raise SystemExit("pdftk dump_data: NumberOfPages not found")
    return int(match.group(1))


def count_pages_node(path: str) -> int:
    base = os.path.dirname(os.path.abspath(path))
    js_path = os.path.join(base, ".count_pdflib_tmp.js")
    with open(js_path, "w", encoding="utf-8") as fh:
        fh.write(JS_COUNT)
    try:
        result = subprocess.run(
            ["node", js_path, path], capture_output=True, text=True
        )
        if result.returncode != 0:
            raise SystemExit(f"node page count failed: {result.stderr.strip()}")
        return int(result.stdout.strip())
    finally:
        if os.path.exists(js_path):
            os.remove(js_path)


def count_pages_stdlib(path: str) -> int:
    with open(path, "rb") as fh:
        return SimplePdf(fh.read()).page_count()


def count_pages(path: str) -> int:
    try:
        return count_pages_pypdf(path)
    except ImportError:
        pass
    try:
        return count_pages_pypdfium2(path)
    except ImportError:
        pass
    if shutil.which("qpdf"):
        return count_pages_qpdf(path)
    if shutil.which("pdftk"):
        return count_pages_pdftk(path)
    if node_pdflib_available():
        return count_pages_node(path)
    return count_pages_stdlib(path)


# ------------------------------------------------------------------ text

def page1_text_pypdf(path: str) -> str:
    from pypdf import PdfReader

    return PdfReader(path).pages[0].extract_text() or ""


def page1_text_pypdfium2(path: str) -> str:
    import pypdfium2 as pdfium

    doc = pdfium.PdfDocument(path)
    try:
        return doc[0].get_text() or ""
    finally:
        doc.close()


def page1_text_pdftotext(path: str) -> str:
    result = subprocess.run(
        ["pdftotext", "-f", "1", "-l", "1", path, "-"],
        capture_output=True,
        text=True,
    )
    if result.returncode != 0:
        raise SystemExit(f"pdftotext failed: {result.stderr.strip()}")
    return result.stdout


def page1_text_stdlib(path: str) -> str:
    """Extract page 1 text-showing strings from the decoded content stream."""
    with open(path, "rb") as fh:
        pdf = SimplePdf(fh.read())
    content = pdf.page_contents(1)
    strings = re.findall(rb"\(((?:[^()\\]|\\.)*)\)\s*Tj", content)
    decoded = []
    for s in strings:
        s = s.replace(b"\\(", b"(").replace(b"\\)", b")").replace(b"\\\\", b"\\")
        decoded.append(s.decode("latin-1"))
    return " ".join(decoded)


def page1_text(path: str) -> str:
    try:
        return page1_text_pypdf(path)
    except ImportError:
        pass
    if shutil.which("pdftotext"):
        return page1_text_pdftotext(path)
    try:
        return page1_text_pypdfium2(path)
    except ImportError:
        pass
    return page1_text_stdlib(path)


# ------------------------------------------------------------- node helper

def node_pdflib_available() -> bool:
    if not shutil.which("node"):
        return False
    code = (
        "const path=require('path');const {execSync}=require('child_process');"
        "let ok=false;"
        "try{require.resolve('pdf-lib');ok=true}catch(e){}"
        "if(!ok){try{require(path.join(execSync('npm root -g').toString().trim(),'pdf-lib'));ok=true}catch(e){}}"
        "process.stdout.write(ok?'yes':'no')"
    )
    try:
        result = subprocess.run(["node", "-e", code], capture_output=True, text=True)
        return result.returncode == 0 and "yes" in result.stdout
    except Exception:
        return False


# ------------------------------------------------------------------- probe

def probe() -> None:
    import importlib

    print(f"report.pdf exists: {os.path.exists(REPORT)}")
    for mod in ("pypdf", "pypdfium2", "reportlab", "PIL", "pdf2image", "fpdf", "fitz"):
        try:
            importlib.import_module(mod)
            print(f"python module {mod}: available")
        except Exception as exc:
            print(f"python module {mod}: unavailable ({type(exc).__name__})")
    for tool in ("qpdf", "pdftk", "pdftotext", "pdftoppm", "gs", "node", "python3"):
        found = shutil.which(tool)
        print(f"cli {tool}: {found if found else 'not found'}")
    print(f"node pdf-lib: {'available' if node_pdflib_available() else 'unavailable'}")


# ------------------------------------------------------------------- main

def main() -> None:
    if len(sys.argv) > 1 and sys.argv[1] == "--probe":
        probe()
        return

    if not os.path.exists(REPORT):
        raise SystemExit(f"error: {REPORT} not found in the working directory")

    cover_bytes, cover_method = build_cover_bytes()
    original_pages = count_pages(REPORT)

    merge_method = None
    try:
        import pypdf  # noqa: F401

        merge_with_pypdf(cover_bytes, REPORT)
        merge_method = "pypdf"
    except ImportError:
        pass
    if merge_method is None:
        try:
            import pypdfium2  # noqa: F401

            merge_with_pypdfium2(cover_bytes, REPORT)
            merge_method = "pypdfium2"
        except ImportError:
            pass
    if merge_method is None and shutil.which("qpdf"):
        cover_path = _write_temp_cover(cover_bytes)
        try:
            merge_with_qpdf(cover_path, REPORT)
            merge_method = "qpdf"
        finally:
            if os.path.exists(cover_path):
                os.remove(cover_path)
    if merge_method is None and shutil.which("pdftk"):
        cover_path = _write_temp_cover(cover_bytes)
        try:
            merge_with_pdftk(cover_path, REPORT)
            merge_method = "pdftk"
        finally:
            if os.path.exists(cover_path):
                os.remove(cover_path)
    if merge_method is None and node_pdflib_available():
        merge_with_node_pdflib(REPORT, DATE_STR)
        merge_method = "node/pdf-lib"
    if merge_method is None:
        try:
            import PIL  # noqa: F401
            import pdf2image  # noqa: F401

            merge_with_pil(cover_bytes, REPORT)
            merge_method = "PIL/pdf2image (raster)"
        except ImportError:
            pass
    if merge_method is None:
        raise SystemExit(
            "no documented merge tool available (pypdf, pypdfium2, qpdf, "
            "pdftk, node/pdf-lib, or PIL/pdf2image)"
        )

    # Validate: page count grew by exactly one and page 1 shows title + date
    final_pages = count_pages(REPORT)
    if final_pages != original_pages + 1:
        raise SystemExit(
            f"validation failed: expected {original_pages + 1} pages, "
            f"got {final_pages}"
        )
    text = page1_text(REPORT)
    if TITLE not in text:
        raise SystemExit("validation failed: cover page title missing")
    if DATE_STR not in text:
        raise SystemExit("validation failed: cover page date missing")

    print(
        f"Cover page prepended (merge via {merge_method}): "
        f"title={TITLE!r}, date={DATE_STR!r}; pages {original_pages} -> {final_pages}"
    )


if __name__ == "__main__":
    main()
